import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.161.0/build/three.module.js';

const mount=document.querySelector('#game');
const scene=new THREE.Scene();scene.background=new THREE.Color(0x899a9b);scene.fog=new THREE.FogExp2(0x899a9b,.0019);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,1800);
const renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;mount.appendChild(renderer.domElement);
scene.add(new THREE.HemisphereLight(0xc9d9e3,0x263129,2.1));const sun=new THREE.DirectionalLight(0xffe6c6,3.2);sun.position.set(-80,120,240);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-100;sun.shadow.camera.right=100;sun.shadow.camera.top=160;sun.shadow.camera.bottom=-50;scene.add(sun);
const mat=(color,roughness=.8,metalness=0)=>new THREE.MeshStandardMaterial({color,roughness,metalness});
const mats={road:mat(0x343a3b,.93),shoulder:mat(0x777974),line:mat(0xe4e1d4),grass:mat(0x455b4a),sand:mat(0xc2a779),ocean:mat(0x46656c,.32,.2),dark:mat(0x111618),pine:mat(0x263d36),pine2:mat(0x344c40),trunk:mat(0x4a392d),metal:mat(0x707a7a,.45,.65),lamp:mat(0xffe7a3,.25),rock:mat(0x72746e),white:mat(0xe4e4dc,.35),red:mat(0xba2825,.35),yellow:mat(0xf0b932,.4),green:mat(0x315e4b,.36)};
function box(parent,x,y,z,sx,sy,sz,material){const m=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),material);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function sphere(parent,x,y,z,r,material,sx=1,sy=1,sz=1){const m=new THREE.Mesh(new THREE.SphereGeometry(r,12,8),material);m.position.set(x,y,z);m.scale.set(sx,sy,sz);m.castShadow=true;parent.add(m);return m}
function roadCenter(z){return Math.sin(z*.0019)*13+Math.sin(z*.0062)*2.1+Math.sin(z*.0007)*7}
// Vast coastal ground, water, and layered distant headlands.
const ground=new THREE.Mesh(new THREE.PlaneGeometry(2000,9000),mats.grass);ground.rotation.x=-Math.PI/2;ground.position.set(0,-.32,3500);ground.receiveShadow=true;scene.add(ground);
const ocean=new THREE.Mesh(new THREE.PlaneGeometry(1800,9000),mats.ocean);ocean.rotation.x=-Math.PI/2;ocean.position.set(-980,-.15,3500);scene.add(ocean);
const headMat=[mat(0x647773),mat(0x718078),mat(0x7d8177)];
for(let row=0;row<3;row++){const points=[];for(let i=0;i<=36;i++){const x=-1300+i*85;points.push(new THREE.Vector3(x,25+Math.sin(i*.62+row)*19+Math.cos(i*.21)*24,-300+row*75));}const curve=new THREE.CatmullRomCurve3(points);const geo=new THREE.BufferGeometry().setFromPoints(curve.getPoints(110));const ridge=new THREE.Mesh(new THREE.TubeGeometry(curve,110,1,5,false),headMat[row]);ridge.position.y=0;scene.add(ridge);const shape=new THREE.Shape();shape.moveTo(-1500,-20);for(let i=0;i<points.length;i++)shape.lineTo(points[i].x,points[i].y);shape.lineTo(1800,-20);shape.lineTo(-1500,-20);const mountain=new THREE.Mesh(new THREE.ShapeGeometry(shape),headMat[row]);mountain.position.z=-300+row*75;scene.add(mountain);}
// Sun disk and soft atmospheric cloud banks.
const sunBall=new THREE.Mesh(new THREE.SphereGeometry(23,24,18),new THREE.MeshBasicMaterial({color:0xffe2b1}));sunBall.position.set(-170,100,-260);scene.add(sunBall);
const clouds=new THREE.Group();scene.add(clouds);for(let i=0;i<28;i++){const x=-650+Math.random()*1300,y=78+Math.random()*86,z=360+Math.random()*700;const c=new THREE.Group();for(let j=0;j<4;j++)sphere(c,j*11,Math.random()*2,0,9+Math.random()*5,mat(i%2?0xa9b8b2:0xb6b8ad),1,.35,.7);c.position.set(x,y,z);clouds.add(c)}
// Road surface uses short chords following the coastal bends.
const roadSegments=[];const trackStart=-240,segLength=22,segCount=290;
for(let i=0;i<segCount;i++){const z=trackStart+i*segLength,zm=z+segLength/2,c=roadCenter(zm);const group=new THREE.Group();group.position.set(c,0,z);scene.add(group);const road=new THREE.Mesh(new THREE.BoxGeometry(13,.25,segLength+.22),mats.road);road.position.y=-.04;road.receiveShadow=true;group.add(road);for(const side of [-1,1]){const edge=new THREE.Mesh(new THREE.BoxGeometry(.24,.035,segLength),mats.line);edge.position.set(side*6.13,.105,0);group.add(edge);const shoulder=new THREE.Mesh(new THREE.BoxGeometry(1.6,.18,segLength),mats.shoulder);shoulder.position.set(side*7.3,-.08,0);group.add(shoulder)}if(i%2===0){const stripe=new THREE.Mesh(new THREE.BoxGeometry(.15,.04,8),mats.line);stripe.position.set(0,.115,0);group.add(stripe)}roadSegments.push(group)}
// Guardrails on exposed coastal stretches and roadside reflector posts.
const rails=[];for(let i=0;i<185;i++){const z=-180+i*34,c=roadCenter(z);for(const side of [-1,1]){if(side<0&&i%7===0)continue;const g=new THREE.Group();g.position.set(c+side*8.6,0,z);scene.add(g);const post=box(g,0,.52,0,.12,1.05,.14,mats.metal);const beam=box(g,0,.85,0,.16,.2,34,mats.metal);rails.push(g)}}
const trees=[];const treeMaterials=[mats.pine,mats.pine2,mat(0x405447),mat(0x304239)];
function makeTree(x,z,scale){const g=new THREE.Group();const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.13,.25,2.6,7),mats.trunk);trunk.position.y=1.25;g.add(trunk);for(let j=0;j<3;j++){const cone=new THREE.Mesh(new THREE.ConeGeometry(1.35-j*.19,2.6,8),treeMaterials[Math.floor(Math.random()*treeMaterials.length)]);cone.position.y=2.15+j*1.25;cone.scale.set(1,1.05,1);cone.castShadow=true;g.add(cone)}g.position.set(x,0,z);g.scale.setScalar(scale);scene.add(g);return g}
for(let i=0;i<220;i++){const z=-160+i*28+(Math.random()-.5)*12,c=roadCenter(z);for(const side of [-1,1]){if(side<0&&i%3===0)continue;trees.push(makeTree(c+side*(12+Math.random()*20),z, .7+Math.random()*.9))}}
// Street lighting, roadside markers and occasional coastal signs.
const streetlights=[];for(let i=0;i<34;i++){const z=-110+i*180,c=roadCenter(z);for(const side of [-1,1]){if(side===-1&&i%2)continue;const g=new THREE.Group();g.position.set(c+side*9.3,0,z);box(g,0,3.4,0,.13,6.8,.13,mats.metal);const arm=box(g,-side*.75,6.7,0,1.6,.12,.13,mats.metal);const bulb=new THREE.Mesh(new THREE.SphereGeometry(.22,8,6),new THREE.MeshBasicMaterial({color:0xffe7a3}));bulb.position.set(-side*1.4,6.55,0);g.add(bulb);scene.add(g);streetlights.push(g)}}
const signs=[];function makeSign(z,side,text){const g=new THREE.Group(),c=roadCenter(z);g.position.set(c+side*10,0,z);box(g,0,1.5,0,.16,3,.18,mats.metal);box(g,0,3.4,0,3.8,1.55,.18,mat(0x17493f));const panel=box(g,0,3.4,.11,3.62,1.36,.06,mat(0x1d6651));const canvas=document.createElement('canvas');canvas.width=512;canvas.height=180;const cx=canvas.getContext('2d');cx.fillStyle='#d9efca';cx.font='bold 34px sans-serif';cx.fillText(text,20,68);cx.font='24px sans-serif';cx.fillText('COASTAL ROUTE  /  EXIT 06',20,120);const texture=new THREE.CanvasTexture(canvas);const face=new THREE.Mesh(new THREE.PlaneGeometry(3.55,1.3),new THREE.MeshBasicMaterial({map:texture,transparent:true}));face.position.set(0,3.4,.16);g.add(face);scene.add(g);signs.push(g)}makeSign(110,1,'PACIFIC POINT');makeSign(720,-1,'LOOKOUT  2 KM');makeSign(1430,1,'SLOW  /  CURVE');

// Player GT coupe: layered bodywork, glass, wheels, lights, mirrors and a subtle rear wing.
const player=new THREE.Group();scene.add(player);const paint=new THREE.MeshPhysicalMaterial({color:0x9d1c1c,metalness:.72,roughness:.24,clearcoat:1,clearcoatRoughness:.12});const glass=new THREE.MeshPhysicalMaterial({color:0x172b32,metalness:.48,roughness:.15,clearcoat:.8});const rubber=mat(0x101212,.86),rim=new THREE.MeshStandardMaterial({color:0xaeb6b4,metalness:.85,roughness:.25});
function customMesh(parent,verts,indices,material){const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(verts,3));geo.setIndex(indices);geo.computeVertexNormals();const obj=new THREE.Mesh(geo,material);obj.castShadow=true;obj.receiveShadow=true;parent.add(obj);return obj}
// sculpted lower body, tapered nose, broad rear quarters
const body=customMesh(player,[
-.82,.4,-2.05,.82,.4,-2.05,-1,.48,-1.45,1,.48,-1.45,-1.02,.52,.9,1.02,.52,.9,-.85,.45,1.95,.85,.45,1.95,
-.82,.82,-1.35,.82,.82,-1.35,-.92,.91,-.6,.92,.91,-.6,-.9,.86,1.35,.9,.86,1.35,-.75,.65,1.95,.75,.65,1.95,
-.68,1.22,-.75,.68,1.22,-.75,-.62,1.27,.55,.62,1.27,.55],
[0,1,9,0,9,8,1,3,9,3,11,9,0,8,2,2,8,10,3,1,12,1,9,12,3,12,11,2,10,4,4,10,13,4,13,12,4,12,3,3,12,13,4,5,13,5,14,13,5,7,15,5,15,14,4,13,6,6,13,14,6,7,14,7,6,14,8,9,16,9,17,16,9,11,17,11,18,17,10,11,18,10,18,16,12,13,18,12,18,17,13,14,18,14,19,18],paint);
// front and rear valances, grille, racing accents, glasshouse
box(player,0,.49,2.025,1.31,.17,.08,mats.dark);box(player,0,.48,2.08,.54,.095,.04,mat(0x737c7b,.4,.7));
const windshield=customMesh(player,[-.65,1.27,.53,.65,1.27,.53,-.59,.84,1.48,.59,.84,1.48], [0,1,2,1,3,2],glass);const rearGlass=customMesh(player,[-.68,1.2,-.77,.68,1.2,-.77,-.84,.85,-1.5,.84,.85,-1.5],[0,2,1,1,2,3],glass);
// roof and side windows
customMesh(player,[-.62,1.27,-.77,.62,1.27,-.77,-.65,1.27,.53,.65,1.27,.53],[0,1,2,1,3,2],paint);
for(const side of [-1,1]){const w=customMesh(player,[side*.83,.9,-.58,side*.83,.9,1.28,side*.65,1.22,-.68,side*.65,1.22,.47],[0,1,2,1,3,2],glass);w.material=glass;box(player,side*.94,.84,.35,.08,.07,1.4,paint);const mirror=sphere(player,side*1,.9,.58,.14,paint,1.5,.65,.8);}
// signature LED lamps, rear lamps, wing and wheels
for(const side of [-1,1]){const head=new THREE.Mesh(new THREE.BoxGeometry(.49,.12,.08),new THREE.MeshBasicMaterial({color:0xe9f7ff}));head.position.set(side*.61,.67,1.89);player.add(head);const tail=new THREE.Mesh(new THREE.BoxGeometry(.46,.13,.08),new THREE.MeshBasicMaterial({color:0xff3128}));tail.position.set(side*.62,.69,-1.99);player.add(tail);box(player,side*.92,.52,-1.6,.12,.12,.36,mats.dark);const wheel=new THREE.Group();wheel.position.set(side*.97,.43,[-1.28,1.25][side<0?0:1]);player.add(wheel);const tire=new THREE.Mesh(new THREE.CylinderGeometry(.4,.4,.27,20),rubber);tire.rotation.z=Math.PI/2;tire.castShadow=true;wheel.add(tire);const hub=new THREE.Mesh(new THREE.CylinderGeometry(.23,.23,.29,14),rim);hub.rotation.z=Math.PI/2;wheel.add(hub);for(let n=0;n<5;n++){const spoke=box(wheel,side*.16,.0,0,.035,.37,.045,rim);spoke.rotation.x=n*Math.PI/5}player.userData.wheels??=[];player.userData.wheels.push(wheel);}
box(player,0,1.05,-1.7,1.8,.12,.16,paint);box(player,0,1.13,-1.75,1.2,.12,.11,mats.dark);
// Moving civilian traffic. Cars have distinguishable paint and light signatures.
const traffic=[],trafficPaint=[mat(0xd4d1c6,.35,.55),mat(0x263e48,.3,.62),mat(0x9c692d,.34,.6),mat(0x50625a,.42,.48),mat(0x282b30,.3,.7)];
function makeTraffic(z,lane,type){const g=new THREE.Group();const color=trafficPaint[Math.floor(Math.random()*trafficPaint.length)];box(g,0,.49,0,1.75,.55,4.0,color);box(g,0,.88,-.25,1.44,.55,1.8,glass);box(g,0,.57,1.97,1.2,.18,.1,mats.dark);for(const side of [-1,1]){const h=new THREE.Mesh(new THREE.BoxGeometry(.42,.12,.06),new THREE.MeshBasicMaterial({color:0xff352a}));h.position.set(side*.58,.64,-2.02);g.add(h);const tire=new THREE.Mesh(new THREE.CylinderGeometry(.35,.35,.23,12),rubber);tire.rotation.z=Math.PI/2;tire.position.set(side*.91,.38,-1.2);g.add(tire);const tire2=tire.clone();tire2.position.z=1.2;g.add(tire2)}g.position.set(roadCenter(z)+lane,.02,z);g.userData={z,lane,type,speed:Math.random()*12+20};scene.add(g);traffic.push(g);return g}
for(let i=0;i<15;i++)makeTraffic(80+i*105,[-3.4,0,3.3][Math.floor(Math.random()*3)],i%4);
// Roadside reflector markers / little shrubs break up the shoulder.
const markers=[];for(let i=0;i<150;i++){const z=-180+i*42,c=roadCenter(z);for(const side of [-1,1]){const g=new THREE.Group();g.position.set(c+side*8.15,.42,z);box(g,0,0,0,.13,.84,.15,mats.white);box(g,0,.16,.09,.16,.18,.04,mats.red);scene.add(g);markers.push(g)}}
// Vehicle controls and driving simulation.
const ui={screen:document.querySelector('#screen'),start:document.querySelector('#start'),title:document.querySelector('#title'),desc:document.querySelector('#desc'),hud:document.querySelector('#hud'),speed:document.querySelector('#speed'),gear:document.querySelector('#gear'),dist:document.querySelector('#distance'),timer:document.querySelector('#timer'),throttle:document.querySelector('#throttle'),pause:document.querySelector('#pause'),note:document.querySelector('#note'),flash:document.querySelector('#flash')};
let started=false,paused=false,dead=false,elapsed=0,runDistance=0,speed=0,steer=0,lateral=0,shake=0,noteTime=0;const keys={};
addEventListener('keydown',e=>{keys[e.code]=true;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();if(e.code==='KeyP'||e.code==='Escape')togglePause();if(e.code==='KeyR'&&dead)resetGame()},{passive:false});addEventListener('keyup',e=>keys[e.code]=false);
function bindHold(id,key){const el=document.querySelector(id);el.addEventListener('pointerdown',e=>{e.preventDefault();keys[key]=true;el.setPointerCapture?.(e.pointerId)});for(const name of ['pointerup','pointercancel','lostpointercapture'])el.addEventListener(name,()=>keys[key]=false)}bindHold('#left','ArrowLeft');bindHold('#right','ArrowRight');bindHold('#gas','ArrowUp');
ui.start.addEventListener('click',()=>{if(dead){resetGame();return}if(paused){togglePause();return}started=true;ui.screen.classList.add('hidden');ui.hud.classList.add('active');ui.pause.classList.add('on');speed=8;});ui.pause.addEventListener('click',togglePause);
function togglePause(){if(!started||dead)return;paused=!paused;if(paused){ui.title.innerHTML='TAKE A<span>BREATHER.</span>';ui.desc.textContent='The road will wait. Catch your breath, then get back out there.';ui.start.innerHTML='<span>RESUME DRIVE</span><span class="arrow">↗</span>';ui.screen.classList.remove('hidden')}else ui.screen.classList.add('hidden')}
function resetGame(){started=false;paused=false;dead=false;elapsed=0;runDistance=0;speed=8;lateral=0;steer=0;player.position.set(roadCenter(0),0,0);traffic.forEach((g,i)=>{g.userData.z=85+i*105;g.userData.lane=[-3.4,0,3.3][i%3];g.position.set(roadCenter(g.userData.z)+g.userData.lane,.02,g.userData.z)});ui.title.innerHTML='NIGHT<span>RUN.</span>';ui.desc.textContent='The coast is yours. Carve through the mountain bends, thread the traffic and keep your line clean. How far can you make it?';ui.start.innerHTML='<span>START YOUR ENGINE</span><span class="arrow">↗</span>';ui.screen.classList.remove('hidden');ui.hud.classList.remove('active');ui.pause.classList.remove('on')}
function crash(){dead=true;started=false;speed=0;ui.title.innerHTML='RUN<span>OVER.</span>';ui.desc.textContent=`You covered ${(runDistance/1000).toFixed(2)} km in ${formatTime(elapsed)}. Every clean pass counts. Think you can go farther?`;ui.start.innerHTML='<span>DRIVE AGAIN</span><span class="arrow">↗</span>';ui.screen.classList.remove('hidden');ui.pause.classList.remove('on');ui.flash.classList.add('hit');setTimeout(()=>ui.flash.classList.remove('hit'),180)}
function formatTime(s){const m=Math.floor(s/60),sec=(s%60).toFixed(1).padStart(4,'0');return `${String(m).padStart(2,'0')}:${sec}`}
function approachTraffic(dt){for(const car of traffic){const d=car.userData;d.z-=Math.max(0,speed-d.speed)*dt;car.position.z=d.z;car.position.x=roadCenter(d.z)+d.lane;const gap=d.z-runDistance;if(gap<5&&gap>-2&&Math.abs(car.position.x-player.position.x)<1.9){crash();return}if(gap<1&&gap>-4&&Math.abs(car.position.x-player.position.x)>2.0){runDistance+=250;ui.note.classList.add('show');noteTime=2.2}if(d.z<runDistance-35){d.z=runDistance+850+Math.random()*500;d.lane=[-3.5,0,3.5][Math.floor(Math.random()*3)];d.speed=18+Math.random()*17;car.position.set(roadCenter(d.z)+d.lane,.02,d.z)}}}
const clock=new THREE.Clock();function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.04);if(started&&!paused){elapsed+=dt;const accelerating=keys.ArrowUp||keys.KeyW,braking=keys.Space||keys.ArrowDown||keys.KeyS;const target=accelerating?76:braking?Math.max(0,speed-1.6):34;speed=THREE.MathUtils.damp(speed,target,accelerating?1.8:braking?8:.35,dt);const direction=(keys.ArrowRight||keys.KeyD?1:0)-(keys.ArrowLeft||keys.KeyA?1:0);steer=THREE.MathUtils.damp(steer,direction,5,dt);lateral+=steer*speed*.105*dt;lateral*=Math.pow(.996,dt*60);runDistance+=speed*(1000/3600)*dt;const z=runDistance;player.position.x=roadCenter(z)+lateral;player.position.z=z;player.rotation.y=-steer*.11+Math.sin(z*.004)*.008;player.rotation.z=-steer*.035;player.userData.wheels.forEach(w=>w.rotation.x+=speed*dt*.03);approachTraffic(dt);if(Math.abs(lateral)>9.7){speed=Math.max(speed-20*dt,12);ui.flash.classList.add('hit');setTimeout(()=>ui.flash.classList.remove('hit'),130)}ui.speed.textContent=String(Math.round(speed*1.35)).padStart(3,'0');ui.gear.textContent=String(Math.min(6,Math.max(1,Math.floor(speed/13)+1));ui.dist.textContent=(runDistance/1000).toFixed(2)+' KM';ui.timer.textContent=formatTime(elapsed);ui.throttle.style.width=`${Math.min(100,speed/76*100)}%`;if(noteTime>0){noteTime-=dt;if(noteTime<=0)ui.note.classList.remove('show')}}
// Follow camera has gentle suspension/steering motion, framing the road horizon.
const playerZ=player.position.z;const camX=roadCenter(playerZ)+lateral*.54-steer*.38;const desired=new THREE.Vector3(camX,4.4,playerZ-10.5);camera.position.lerp(desired,1-Math.exp(-dt*2.7));const look=new THREE.Vector3(roadCenter(playerZ+28)+lateral*.16,1.15,playerZ+28);camera.lookAt(look);camera.fov=THREE.MathUtils.damp(camera.fov,54+speed*.075,2,dt);camera.updateProjectionMatrix();renderer.render(scene,camera)}animate();
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});

